(4611747, 663954, 90777, '<td valign="top">Maybe its my monitor viewing angle, but i''m seeing a weird halo around the flames</td>', 'Maybe its my monitor viewing angle, but i''m seeing a weird halo around the flames', '2008-04-03 19:19:22.000000', NULL, 1),
(4611752, 664947, 90777, '<td valign="top">Unscored</td>', 'Unscored', '2008-04-03 19:21:26.000000', NULL, 1),
(4611757, 663683, 90777, '<td valign="top">Lovely.  Smoke from a frozen flower?  Excellent lighting</td>', 'Lovely.  Smoke from a frozen flower?  Excellent lighting', '2008-04-03 19:22:16.000000', NULL, 1),
(4611760, 663051, 90777, '<td valign="top">Great macro work</td>', 'Great macro work', '2008-04-03 19:23:09.000000', NULL, 1),
(4611761, 664239, 90777, '<td valign="top">Wow!  Very cool ;-)</td>', 'Wow!  Very cool ;-)', '2008-04-03 19:23:30.000000', NULL, 1),
(4611763, 664978, 90777, '<td valign="top">possibly a little oversharpened?</td>', 'possibly a little oversharpened?', '2008-04-03 19:24:15.000000', NULL, 1),
