(4611774, 663181, 90777, '<td valign="top">the only thing that lets this down are the pencils at 9 o''clock and 3.30 aren''t as sharp (pointed) as the others.  Just noticed the ''hair'' just past 12 as well.  Nonetheless a great concept and well executed.</td>', 'the only thing that lets this down are the pencils at 9 o''clock and 3.30 aren''t as sharp (pointed) as the others.  Just noticed the ''hair'' just past 12 as well.  Nonetheless a great concept and well executed.', '2008-04-03 19:27:53.000000', NULL, 1),
(4611781, 663763, 90777, '<td valign="top">very very good 9</td>', 'very very good 9', '2008-04-03 19:29:04.000000', NULL, 1),
(4611785, 662399, 90777, '<td valign="top">ok it''s heating up at the feeder, but your main colour seems to be green, which isn''t a warm colour.  Sorry</td>', 'ok it''s heating up at the feeder, but your main colour seems to be green, which isn''t a warm colour.  Sorry', '2008-04-03 19:30:13.000000', NULL, 1),
(4611811, 664848, 90777, '<td valign="top">A great concept and a well executed image but I don''t feel your border adds anything to the finished product.</td>', 'A great concept and a well executed image but I don''t feel your border adds anything to the finished product.', '2008-04-03 19:37:08.000000', NULL, 1),
(4611813, 664873, 29513, '<td valign="top">Great shot.  I find the zipper a bit distracting, though.</td>', 'Great shot.  I find the zipper a bit distracting, though.', '2008-04-03 19:37:51.000000', NULL, 1),
(4611817, 662368, 90777, '<td valign="top">good use of a photo brolly!  Image too sharp?</td>', 'good use of a photo brolly!  Image too sharp?', '2008-04-03 19:38:46.000000', NULL, 1),
(4611826, 662786, 90777, '<td valign="top">sorry, this is just way too dark.  If your camera will let you, try using a longer shutter speed, or a larger aperture to allow more light in to your camera.</td>', 'sorry, this is just way too dark.  If your camera will let you, try using a longer shutter speed, or a larger aperture to allow more light in to your camera.', '2008-04-03 19:41:02.000000', NULL, 1),
(4611827, 665041, 29513, '<td valign="top">Nice and sharp and I like your framing.  Might have tried for more contrast, though.</td>', 'Nice and sharp and I like your framing.  Might have tried for more contrast, though.', '2008-04-03 19:41:31.000000', NULL, 1),
