(4613784, 662606, 58457, '<td valign="top">Interesting misty yellows in this.  also the structure adds some mystery as well.</td>', 'Interesting misty yellows in this.  also the structure adds some mystery as well.', '2008-04-04 13:05:38.000000', NULL, 1),
(4613786, 664899, 58457, '<td valign="top">Interesting abstract minimalism going on here.  I think I''d like a bit less of the black.</td>', 'Interesting abstract minimalism going on here.  I think I''d like a bit less of the black.', '2008-04-04 13:06:27.000000', NULL, 1),
