(4613792, 663790, 58457, '<td valign="top">The branch has nice detail, but I''d like to see more going on here.</td>', 'The branch has nice detail, but I''d like to see more going on here.', '2008-04-04 13:08:50.000000', NULL, 1),
(4613794, 664779, 58457, '<td valign="top">The horses are nice and sharp, and I like the snow being kicked up but they don''t fit the theme as well as others in this challenge to me.</td>', 'The horses are nice and sharp, and I like the snow being kicked up but they don''t fit the theme as well as others in this challenge to me.', '2008-04-04 13:09:23.000000', NULL, 1),
