(4613815, 663195, 58457, '<td valign="top">nice hazy shot and the reflection is cool</td>', 'nice hazy shot and the reflection is cool', '2008-04-04 13:12:37.000000', NULL, 1),
(4613818, 663300, 58457, '<td valign="top">This is ok, but doesn''t fit the theme as well as others.  I think your middle of the day light didn''t help</td>', 'This is ok, but doesn''t fit the theme as well as others.  I think your middle of the day light didn''t help', '2008-04-04 13:13:13.000000', NULL, 1),
(4613819, 665091, 58457, '<td valign="top">Nice little still life. Personally I''d like just a little more light for detail in the beans on the right side.</td>', 'Nice little still life. Personally I''d like just a little more light for detail in the beans on the right side.', '2008-04-04 13:13:42.000000', NULL, 1),
