(4616149, 663465, 58457, '<td valign="top">I can''t decide if shooting this through the window pane does this photo justice, or takes away from it.... hmmm.</td>', 'I can''t decide if shooting this through the window pane does this photo justice, or takes away from it.... hmmm.', '2008-04-05 12:08:58.000000', NULL, 1),
(4616150, 664670, 58457, '<td valign="top">I''d like more light on the front child''s face.  Also, not a lot of warm colors going on here.</td>', 'I''d like more light on the front child''s face.  Also, not a lot of warm colors going on here.', '2008-04-05 12:09:34.000000', NULL, 1),
(4616153, 662399, 58457, '<td valign="top">The birds are quite expressive, but I think your green BG takes away from the warm colors.</td>', 'The birds are quite expressive, but I think your green BG takes away from the warm colors.', '2008-04-05 12:10:09.000000', NULL, 1),
(4616155, 662786, 58457, '<td valign="top">Just too dark to tell whats going on here.  Plus the mystery of the brick building evaporates when you see the car parked in front of it.</td>', 'Just too dark to tell whats going on here.  Plus the mystery of the brick building evaporates when you see the car parked in front of it.', '2008-04-05 12:10:48.000000', NULL, 1),
(4616156, 664360, 58457, '<td valign="top">Composition would be strong, but the whole thing is out of focus.</td>', 'Composition would be strong, but the whole thing is out of focus.', '2008-04-05 12:11:24.000000', NULL, 1),
(4616159, 664412, 58457, '<td valign="top">can you believe we eat THAT?  yikes.  WEll, you got a big pile of greasy food here, but I think thats all you may have.</td>', 'can you believe we eat THAT?  yikes.  WEll, you got a big pile of greasy food here, but I think thats all you may have.', '2008-04-05 12:12:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4616161, 663692, 58457, '<td valign="top">I really think I''d like a kid on that thing to garner more interest.</td>', 'I really think I''d like a kid on that thing to garner more interest.', '2008-04-05 12:12:31.000000', NULL, 1),
(4616164, 664431, 58457, '<td valign="top">Nice location.  I''d love to see this at dusk or dawn and w/ some clouds in the sky.</td>', 'Nice location.  I''d love to see this at dusk or dawn and w/ some clouds in the sky.', '2008-04-05 12:13:15.000000', NULL, 1),
(4616167, 662692, 58457, '<td valign="top">I think I''d rather have your subject blocking out the sun.</td>', 'I think I''d rather have your subject blocking out the sun.', '2008-04-05 12:13:43.000000', NULL, 1),
(4616168, 665106, 58457, '<td valign="top">I''d like something more in this photograph to draw my eye to.</td>', 'I''d like something more in this photograph to draw my eye to.', '2008-04-05 12:14:08.000000', NULL, 1),
(4616171, 664701, 58457, '<td valign="top">I just can''t tell what this is.  If you are going for an abstract, you succeeded, but there just isn''t enough recognizable for me.</td>', 'I just can''t tell what this is.  If you are going for an abstract, you succeeded, but there just isn''t enough recognizable for me.', '2008-04-05 12:14:43.000000', NULL, 1),
(4616173, 662467, 58457, '<td valign="top">unfortunately, your flower doesn''t really look warm and fuzzy.  I think the background is a bit harsh, an the flower is too sharp.  Maybe cast some shade over the flower next time?</td>', 'unfortunately, your flower doesn''t really look warm and fuzzy.  I think the background is a bit harsh, an the flower is too sharp.  Maybe cast some shade over the flower next time?', '2008-04-05 12:15:51.000000', NULL, 1),
(4616176, 663353, 58457, '<td valign="top">Lighting just didn''t help you in this one.  Your kettles just don''t have much definition.</td>', 'Lighting just didn''t help you in this one.  Your kettles just don''t have much definition.', '2008-04-05 12:16:22.000000', NULL, 1),
(4616177, 664947, 58457, '<td valign="top">Its bit blurry, and I think if this is a quilt I''d rather see it wrapped around somebody or draped over somehting.</td>', 'Its bit blurry, and I think if this is a quilt I''d rather see it wrapped around somebody or draped over somehting.', '2008-04-05 12:17:04.000000', NULL, 1),
(4616178, 662807, 58457, '<td valign="top">Just not enough going on here.</td>', 'Just not enough going on here.', '2008-04-05 12:17:21.000000', NULL, 1),
(4616179, 662367, 58457, '<td valign="top">I think you mistook the warm theme--violet and green are cool colors, you probably would''ve scored a point higher in that challenge.</td>', 'I think you mistook the warm theme--violet and green are cool colors, you probably would''ve scored a point higher in that challenge.', '2008-04-05 12:17:56.000000', NULL, 1),
(4616180, 664267, 58457, '<td valign="top">Just nothing here that fits the theme--he is too multicolored, even the balloon he is blowing up is a cool color.</td>', 'Just nothing here that fits the theme--he is too multicolored, even the balloon he is blowing up is a cool color.', '2008-04-05 12:18:36.000000', NULL, 1),
