(4618317, 664229, 34255, '<td valign="top">Fits the challenge well, nice sharp image.  I don''t like the border, and the combination of red and yellow reminds me of McDonald''s. Maybe a different background color would work better.</td>', 'Fits the challenge well, nice sharp image.  I don''t like the border, and the combination of red and yellow reminds me of McDonald''s. Maybe a different background color would work better.', '2008-04-06 12:43:45.000000', NULL, 1),
(4618498, 664198, 68346, '<td valign="top">i have been trying forever to get a shot like this, but the little blighters move too fast for me!<br/>real good job.</td>', 'i have been trying forever to get a shot like this, but the little blighters move too fast for me!real good job.', '2008-04-06 14:28:31.000000', NULL, 1),
(4618544, 664791, 83313, '<td valign="top">Rolling in leaves? Good lighting and details on the face.</td>', 'Rolling in leaves? Good lighting and details on the face.', '2008-04-06 15:08:27.000000', NULL, 1),
(4618545, 664822, 83313, '<td valign="top">The expected warm colors entry, but nicely done.</td>', 'The expected warm colors entry, but nicely done.', '2008-04-06 15:09:06.000000', NULL, 1),
