(4622260, 663989, 83313, '<td valign="top">Nice colors, unfortunately, I find no interesting composition at all in this. If that bit of tree were not barely in the frame, it might be a decent abstract. An average snapshot, I''m afraid. Sorry to sound so harsh.</td>', 'Nice colors, unfortunately, I find no interesting composition at all in this. If that bit of tree were not barely in the frame, it might be a decent abstract. An average snapshot, I''m afraid. Sorry to sound so harsh.', '2008-04-07 23:04:54.000000', NULL, 1),
(4622267, 664738, 83313, '<td valign="top">This cat looks like it wants food. Eyes could be a bit sharper, the focus seems more on the nose. Otherwise, a nice and detailed image.</td>', 'This cat looks like it wants food. Eyes could be a bit sharper, the focus seems more on the nose. Otherwise, a nice and detailed image.', '2008-04-07 23:06:35.000000', NULL, 1),
(4622275, 663428, 90806, '<td valign="top">stunningly beautiful</td>', 'stunningly beautiful', '2008-04-07 23:08:57.000000', NULL, 1),
(4622276, 663195, 90806, '<td valign="top">Very pretty.  Could see this as a movie poster or something, perhaps a poem across the sky.  Very tasteful border.</td>', 'Very pretty.  Could see this as a movie poster or something, perhaps a poem across the sky.  Very tasteful border.', '2008-04-07 23:09:00.000000', NULL, 1),
(4622277, 663192, 90806, '<td valign="top">Great colors and detail and feeling of motion with the diagonal. One of my favorites of this challenge.</td>', 'Great colors and detail and feeling of motion with the diagonal. One of my favorites of this challenge.', '2008-04-07 23:09:06.000000', NULL, 1),
(4622280, 664993, 90806, '<td valign="top">Great title.  I can picture the longing with it right at the edge like that.</td>', 'Great title.  I can picture the longing with it right at the edge like that.', '2008-04-07 23:09:10.000000', NULL, 1),
(4622281, 664814, 90806, '<td valign="top">Beautiful detail and color.  Peaceful.</td>', 'Beautiful detail and color.  Peaceful.', '2008-04-07 23:09:15.000000', NULL, 1),
(4622282, 664955, 90806, '<td valign="top">A nice warm photo too.  Love the detail in the woodgrain and yarn.</td>', 'A nice warm photo too.  Love the detail in the woodgrain and yarn.', '2008-04-07 23:09:19.000000', NULL, 1),
(4622283, 664933, 83313, '<td valign="top">File size is only 51k, it compressed well because of the large black background, but you may have been able to squeeze some more detail in the subject if you had used less compression. No obvious artifacts, however, and it''s pretty darn good. (I''m just the JPEG police is all it is!)</td>', 'File size is only 51k, it compressed well because of the large black background, but you may have been able to squeeze some more detail in the subject if you had used less compression. No obvious artifacts, however, and it''s pretty darn good. (I''m just the JPEG police is all it is!)', '2008-04-07 23:09:22.000000', NULL, 1),
(4622284, 663087, 90806, '<td valign="top">awesome.  the angled head really makes it look like it is coming to get you.</td>', 'awesome.  the angled head really makes it look like it is coming to get you.', '2008-04-07 23:09:24.000000', NULL, 1),
