(4622304, 664238, 90806, '<td valign="top">lol, love the title.  really like the composition, subject choice and colors too.  Nice and crisp.</td>', 'lol, love the title.  really like the composition, subject choice and colors too.  Nice and crisp.', '2008-04-07 23:11:00.000000', NULL, 1),
(4622305, 663962, 90806, '<td valign="top">Thats hot!  The sky looks a little grainy, but I still love it.</td>', 'Thats hot!  The sky looks a little grainy, but I still love it.', '2008-04-07 23:11:04.000000', NULL, 1),
(4622307, 663051, 90806, '<td valign="top">Pretty and whimsical.</td>', 'Pretty and whimsical.', '2008-04-07 23:11:07.000000', NULL, 1),
(4622308, 665106, 90806, '<td valign="top">Now that looks hot!</td>', 'Now that looks hot!', '2008-04-07 23:11:10.000000', NULL, 1),
