(4622323, 664985, 90806, '<td valign="top">Nice bright yellow and orange and I like youthful activity implied by the nice warm red on the forehead.</td>', 'Nice bright yellow and orange and I like youthful activity implied by the nice warm red on the forehead.', '2008-04-07 23:12:30.000000', NULL, 1),
