(4622347, 664733, 83313, '<td valign="top">Nice, though I think the focus needed to be on the points of the pencils, or it needed better overall DOF.</td>', 'Nice, though I think the focus needed to be on the points of the pencils, or it needed better overall DOF.', '2008-04-07 23:15:11.000000', NULL, 1),
(4622350, 664692, 90806, '<td valign="top">I like the lighting.  The background makes me think of a formal portrait, so maybe judgment is for the photographer!</td>', 'I like the lighting.  The background makes me think of a formal portrait, so maybe judgment is for the photographer!', '2008-04-07 23:17:52.000000', NULL, 1),
